-- =====================================================================
--  UPDATE SCRIPT — ceb_uva_ams
--  Brings an EXISTING database up to the current schema and loads the
--  segment and switch workbooks.
--
--  Built and tested against your own dump (ceb_uva_ams.sql, exported
--  08 Sep 2026, MariaDB 10.4.32). Your data is preserved: no table that
--  holds your records is dropped, and no existing row is deleted.
--
--  WHAT THIS SCRIPT DOES
--    1. Repairs four views that phpMyAdmin truncated during export
--    2. Adds the auth columns and password_resets  (was migration 002)
--    3. Adds switchgear and the segment register   (was migration 003)
--    4. Loads 1355 switches and 1325 segments from the workbooks
--    5. Adds the reporting views for both
--
--  BACK UP FIRST
--    mysqldump -u root ceb_uva_ams > backup_before_update.sql
--
--  RUN IT
--    mysql -u root ceb_uva_ams < UPDATE_ceb_uva_ams.sql
--  or import through phpMyAdmin with ceb_uva_ams already selected.
--
--  Uses MariaDB's ADD COLUMN IF NOT EXISTS, so it is safe to run twice.
--  You are on 10.4.32, which supports it. MySQL 8 does not.
-- =====================================================================

USE ceb_uva_ams;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;


-- =====================================================================
-- SECTION 1 — REPAIR THE TRUNCATED VIEWS
--
-- Your export cut off mid-statement inside v_transformer_data_quality:
--   ... `tx`.`transformer_id` AS `
-- and phpMyAdmin also emitted "nullunion allselect" with the spaces lost.
-- Everything after that line failed to import, taking three more views
-- with it. These five definitions restore them.
--
-- This is an export bug, not damage to your live database. But re-import
-- that dump anywhere and you would lose these, so they are rebuilt here.
-- =====================================================================

CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_transformer_rollup AS
SELECT
    tx.transformer_id,
    tx.old_sin_no,
    tx.new_sin_no,
    tx.substation_name,
    tx.transformer_type,
    tx.capacity_kva,
    tx.transformer_no,
    tx.quantity,
    tx.condition_status,
    tx.status,
    tx.node_id,
    tx.asset_id,
    tx.asset_type_id,
    t.type_code,
    t.type_name,
    tx.csc_id,
    d.csc_code,
    d.csc_name,
    d.area_id,
    ar.area_code,
    ar.area_name,
    ar.province_id,
    p.province_name
FROM transformers tx
JOIN csc_depots  d  ON d.csc_id      = tx.csc_id
JOIN areas       ar ON ar.area_id    = d.area_id
JOIN provinces   p  ON p.province_id = ar.province_id
LEFT JOIN asset_types t ON t.asset_type_id = tx.asset_type_id
WHERE tx.status = 'ACTIVE';


-- Depot-level transformer counts and installed capacity.;


CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_transformer_totals_by_csc AS
SELECT province_id, province_name, area_id, area_code, area_name,
       csc_id, csc_code, csc_name,
       COUNT(*)                                    AS transformer_records,
       SUM(quantity)                               AS transformer_units,
       SUM(COALESCE(capacity_kva, 0) * quantity)   AS installed_kva
FROM v_transformer_rollup
GROUP BY province_id, province_name, area_id, area_code, area_name,
         csc_id, csc_code, csc_name;


CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_transformer_totals_by_area AS
SELECT province_id, province_name, area_id, area_code, area_name,
       COUNT(*)                                    AS transformer_records,
       SUM(quantity)                               AS transformer_units,
       SUM(COALESCE(capacity_kva, 0) * quantity)   AS installed_kva
FROM v_transformer_rollup
GROUP BY province_id, province_name, area_id, area_code, area_name;


-- Capacity mix for the dashboard doughnut chart, from real nameplate data.;


CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_transformer_capacity_mix AS
SELECT province_id, area_id, area_name, csc_id, csc_name,
       capacity_kva,
       transformer_type,
       COUNT(*)                                    AS unit_count,
       SUM(COALESCE(capacity_kva, 0) * quantity)   AS installed_kva
FROM v_transformer_rollup
WHERE capacity_kva IS NOT NULL
GROUP BY province_id, area_id, area_name, csc_id, csc_name,
         capacity_kva, transformer_type;


-- ---------------------------------------------------------------------
-- v_depot_dashboard : one row per depot, the headline numbers.
-- This is what the depot landing page and the province summary read.
-- ---------------------------------------------------------------------;


CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_transformer_data_quality AS
SELECT 'TX_NO_SIN' AS issue_code, 'WARNING' AS severity,
       tx.transformer_id AS entity_id, tx.csc_id,
       CONCAT('Transformer at "', tx.substation_name, '" has no SIN number.') AS description
FROM transformers tx
WHERE tx.status = 'ACTIVE' AND tx.old_sin_no IS NULL AND tx.new_sin_no IS NULL

UNION ALL
SELECT 'TX_NO_SERIAL', 'INFO', tx.transformer_id, tx.csc_id,
       CONCAT('Transformer at "', tx.substation_name, '" has no serial / plate number.')
FROM transformers tx
WHERE tx.status = 'ACTIVE' AND tx.transformer_no IS NULL

UNION ALL
SELECT 'TX_NO_CAPACITY', 'ERROR', tx.transformer_id, tx.csc_id,
       CONCAT('Transformer at "', tx.substation_name, '" has no kVA rating, ',
              'so it is missing from every capacity total.')
FROM transformers tx
WHERE tx.status = 'ACTIVE' AND tx.capacity_kva IS NULL

UNION ALL
SELECT 'TX_NOT_ON_NETWORK', 'INFO', tx.transformer_id, tx.csc_id,
       CONCAT('Transformer at "', tx.substation_name, '" is not linked to a network node yet.')
FROM transformers tx
WHERE tx.status = 'ACTIVE' AND tx.node_id IS NULL

UNION ALL
SELECT 'TX_DUPLICATE_SERIAL', 'WARNING', tx.transformer_id, tx.csc_id,
       CONCAT('Serial number ', tx.transformer_no, ' appears on more than one transformer.')
FROM transformers tx
JOIN (SELECT transformer_no FROM transformers
       WHERE transformer_no IS NOT NULL AND status = 'ACTIVE'
       GROUP BY transformer_no HAVING COUNT(*) > 1) dup
  ON dup.transformer_no = tx.transformer_no
WHERE tx.status = 'ACTIVE';


-- =====================================================================
-- SECTION 2 — AUTH SUPPORT  (previously migration 002)
--
-- Self-registered accounts get the VIEWER role and NO depot scope, so
-- they can read dashboards but cannot write any depot's data until an
-- administrator assigns a role and depot. That satisfies FR-1.7 without
-- closing registration.
-- =====================================================================

ALTER TABLE users
    ADD COLUMN IF NOT EXISTS phone VARCHAR(25) NULL AFTER email,
    ADD COLUMN IF NOT EXISTS registration_source
        ENUM('ADMIN_CREATED','SELF_REGISTERED') NOT NULL DEFAULT 'ADMIN_CREATED'
        AFTER phone,
    ADD COLUMN IF NOT EXISTS scope_assigned TINYINT(1) NOT NULL DEFAULT 1
        AFTER registration_source,
    ADD COLUMN IF NOT EXISTS email_verified_at DATETIME NULL AFTER scope_assigned;

ALTER TABLE users
    ADD KEY IF NOT EXISTS ix_users_phone (phone),
    ADD KEY IF NOT EXISTS ix_users_source (registration_source);

-- Your four seeded accounts were created by an administrator.
UPDATE users
   SET registration_source = 'ADMIN_CREATED', scope_assigned = 1
 WHERE user_id <= 4;

-- user_id 5 (gayanthikamanmali2001@gmail.com) registered through the app,
-- so it is marked as self-registered and awaiting a scope assignment.
UPDATE users
   SET registration_source = 'SELF_REGISTERED', scope_assigned = 0
 WHERE user_id = 5 AND csc_id IS NULL AND area_id IS NULL;


-- Password reset tokens. Only a SHA-256 hash is stored; the plain token
-- exists in the emailed link and nowhere else, so a database leak cannot
-- be used to reset anyone's password.
CREATE TABLE IF NOT EXISTS password_resets (
    reset_id     BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id      INT UNSIGNED NOT NULL,
    token_hash   CHAR(64)     NOT NULL,
    expires_at   DATETIME     NOT NULL,
    used_at      DATETIME     NULL,
    requested_ip VARCHAR(45)  NULL,
    created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (reset_id),
    UNIQUE KEY uq_reset_token (token_hash),
    KEY ix_reset_user (user_id),
    KEY ix_reset_expiry (expires_at),
    CONSTRAINT fk_reset_user FOREIGN KEY (user_id)
        REFERENCES users (user_id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_pending_users AS
SELECT u.user_id, u.username, u.full_name, u.email, u.phone,
       u.created_at, r.role_code, r.role_name
FROM users u
JOIN roles r ON r.role_id = u.role_id
WHERE u.registration_source = 'SELF_REGISTERED'
  AND u.scope_assigned = 0
  AND u.is_active = 1;


-- =====================================================================
-- SECTION 3 — SEGMENT AND SWITCH REGISTERS  (previously migration 003)
--
-- Source workbooks:
--   CSC_Segment_Details_-_E.xlsx   1325 segments across 17 depots
--   Switch_List_2025_NEW.xlsx      1355 switches across 17 depots
--
-- WHY NEW TABLES RATHER THAN THE EXISTING `segments`
-- Your `segments` table is the GRAPH: every row needs a from_node_id and
-- a to_node_id. These spreadsheets have no topology at all — a segment
-- code, a feeder, a length, and lists of what sits on the line, but never
-- the two endpoints. Forcing them in would mean inventing 2650
-- nodes nobody surveyed.
--
-- So they land in registers that count today and carry a nullable link
-- into the graph for later, exactly as the transformer register does:
--     segment_register.csc_id     NOT NULL — rolls up now
--     segment_register.segment_id NULL     — fill in once endpoints exist
--     switchgear.csc_id           NOT NULL — rolls up now
--     switchgear.node_id          NULL     — fill in once the node exists
--
-- Link resolution against YOUR transformer data:
--     switch references    2822 total,  2013 matched the switch list
--     transformer refs     2213 total,  1000 matched your register
-- Unmatched references are kept as raw text and reported, not dropped.
-- =====================================================================

-- Seven feeders serving Uva depots originate at Balangoda, Embilipitiya,
-- Hambanthota or Nuwara Eliya. origin_csc_id cannot name a Uva depot for
-- those, so it becomes nullable and external_source records the origin.
ALTER TABLE feeders
    MODIFY COLUMN origin_csc_id INT UNSIGNED NULL,
    ADD COLUMN IF NOT EXISTS external_source VARCHAR(80) NULL AFTER source_name;

ALTER TABLE feeders
    ADD KEY IF NOT EXISTS ix_feeder_external (external_source);


SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS segment_transformer;
DROP TABLE IF EXISTS segment_switchgear;
DROP TABLE IF EXISTS segment_register;
DROP TABLE IF EXISTS switchgear;
SET FOREIGN_KEY_CHECKS = 1;


CREATE TABLE switchgear (
    switchgear_id      INT UNSIGNED NOT NULL AUTO_INCREMENT,
    csc_id             INT UNSIGNED NOT NULL,
    asset_type_id      INT UNSIGNED NULL,
    node_id            INT UNSIGNED NULL,
    asset_id           BIGINT UNSIGNED NULL,
    switch_code        VARCHAR(30)  NOT NULL,
    switch_name        VARCHAR(200) NULL,
    nearest_substation VARCHAR(120) NULL,
    status             ENUM('ACTIVE','PLANNED','RETIRED') NOT NULL DEFAULT 'ACTIVE',
    remarks            TEXT         NULL,
    source_file        VARCHAR(80)  NULL,
    created_at         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
                                    ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (switchgear_id),
    UNIQUE KEY uq_switch_code (switch_code),
    KEY ix_sw_csc (csc_id),
    KEY ix_sw_type (asset_type_id),
    KEY ix_sw_node (node_id),
    KEY ix_sw_substation (nearest_substation),
    CONSTRAINT fk_sw_csc FOREIGN KEY (csc_id)
        REFERENCES csc_depots (csc_id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_sw_type FOREIGN KEY (asset_type_id)
        REFERENCES asset_types (asset_type_id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_sw_node FOREIGN KEY (node_id)
        REFERENCES network_nodes (node_id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_sw_asset FOREIGN KEY (asset_id)
        REFERENCES assets (asset_id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE segment_register (
    register_id   INT UNSIGNED NOT NULL AUTO_INCREMENT,
    csc_id        INT UNSIGNED NOT NULL,
    feeder_id     INT UNSIGNED NULL,
    segment_id    INT UNSIGNED NULL,
    segment_code  VARCHAR(30)  NOT NULL,
    length_km     DECIMAL(9,4) NULL,
    voltage_level ENUM('33kV','11kV','400V') NOT NULL DEFAULT '33kV',
    status        ENUM('ACTIVE','PLANNED','RETIRED') NOT NULL DEFAULT 'ACTIVE',
    remarks       TEXT         NULL,
    source_file   VARCHAR(80)  NULL,
    created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
                               ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (register_id),
    UNIQUE KEY uq_seg_reg (csc_id, segment_code),
    KEY ix_sr_feeder (feeder_id),
    KEY ix_sr_segment (segment_id),
    KEY ix_sr_code (segment_code),
    CONSTRAINT fk_sr_csc FOREIGN KEY (csc_id)
        REFERENCES csc_depots (csc_id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_sr_feeder FOREIGN KEY (feeder_id)
        REFERENCES feeders (feeder_id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_sr_segment FOREIGN KEY (segment_id)
        REFERENCES segments (segment_id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT chk_sr_length CHECK (length_km IS NULL OR (length_km >= 0 AND length_km <= 500))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- switch_ref and transformer_ref keep the spreadsheet text exactly as it
-- was, so a reference that does not resolve stays visible instead of
-- being silently dropped.
CREATE TABLE segment_switchgear (
    link_id       INT UNSIGNED NOT NULL AUTO_INCREMENT,
    register_id   INT UNSIGNED NOT NULL,
    switchgear_id INT UNSIGNED NULL,
    switch_ref    VARCHAR(30)  NOT NULL,
    PRIMARY KEY (link_id),
    UNIQUE KEY uq_seg_sw (register_id, switch_ref),
    KEY ix_ss_switch (switchgear_id),
    KEY ix_ss_ref (switch_ref),
    CONSTRAINT fk_ss_register FOREIGN KEY (register_id)
        REFERENCES segment_register (register_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_ss_switch FOREIGN KEY (switchgear_id)
        REFERENCES switchgear (switchgear_id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE segment_transformer (
    link_id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    register_id     INT UNSIGNED NOT NULL,
    transformer_id  BIGINT UNSIGNED NULL,
    transformer_ref VARCHAR(60) NOT NULL,
    PRIMARY KEY (link_id),
    UNIQUE KEY uq_seg_tx (register_id, transformer_ref),
    KEY ix_st_tx (transformer_id),
    KEY ix_st_ref (transformer_ref),
    CONSTRAINT fk_st_register FOREIGN KEY (register_id)
        REFERENCES segment_register (register_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_st_tx FOREIGN KEY (transformer_id)
        REFERENCES transformers (transformer_id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


