-- SECTION 8 — SEGMENT TO TRANSFORMER LINKS
-- =====================================================================














-- =====================================================================
-- SECTION 9 — REPORTING VIEWS
-- =====================================================================

CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_line_length_by_csc AS
SELECT d.csc_id, d.csc_code, d.csc_name, a.area_id, a.area_name,
       COUNT(*)                    AS segment_count,
       SUM(sr.length_km)           AS total_km,
       ROUND(AVG(sr.length_km), 3) AS mean_km,
       MAX(sr.length_km)           AS longest_km
FROM segment_register sr
JOIN csc_depots d ON d.csc_id = sr.csc_id
JOIN areas a      ON a.area_id = d.area_id
WHERE sr.status = 'ACTIVE'
GROUP BY d.csc_id, d.csc_code, d.csc_name, a.area_id, a.area_name;


CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_line_length_by_feeder AS
SELECT f.feeder_id, f.feeder_code, f.feeder_name,
       f.origin_csc_id, f.external_source,
       COUNT(DISTINCT sr.csc_id) AS depots_crossed,
       COUNT(*)                  AS segment_count,
       SUM(sr.length_km)         AS total_km
FROM segment_register sr
JOIN feeders f ON f.feeder_id = sr.feeder_id
WHERE sr.status = 'ACTIVE'
GROUP BY f.feeder_id, f.feeder_code, f.feeder_name, f.origin_csc_id, f.external_source;


CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_switchgear_by_csc AS
SELECT d.csc_id, d.csc_code, d.csc_name, a.area_id, a.area_name,
       t.type_code, t.type_name, COUNT(*) AS switch_count
FROM switchgear sw
JOIN csc_depots d ON d.csc_id = sw.csc_id
JOIN areas a      ON a.area_id = d.area_id
LEFT JOIN asset_types t ON t.asset_type_id = sw.asset_type_id
WHERE sw.status = 'ACTIVE'
GROUP BY d.csc_id, d.csc_code, d.csc_name, a.area_id, a.area_name,
         t.type_code, t.type_name;


CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_segment_detail AS
SELECT sr.register_id, sr.segment_code, sr.length_km,
       sr.csc_id, d.csc_name, a.area_name,
       f.feeder_code, f.feeder_name, f.external_source,
       (SELECT COUNT(*) FROM segment_switchgear ss WHERE ss.register_id = sr.register_id)
           AS switch_count,
       (SELECT COUNT(*) FROM segment_transformer st WHERE st.register_id = sr.register_id)
           AS transformer_count,
       sr.segment_id IS NOT NULL AS is_on_graph
FROM segment_register sr
JOIN csc_depots d ON d.csc_id = sr.csc_id
JOIN areas a      ON a.area_id = d.area_id
LEFT JOIN feeders f ON f.feeder_id = sr.feeder_id
WHERE sr.status = 'ACTIVE';


-- Segment pairs that share a switch, and therefore physically meet.
-- Where the two belong to different depots, the line crosses a boundary
-- and ownership rule BR-6 says it should be split there.
CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_segment_adjacency AS
SELECT DISTINCT
       a.register_id   AS register_id_a, ra.segment_code AS segment_a,
       b.register_id   AS register_id_b, rb.segment_code AS segment_b,
       a.switch_ref    AS shared_switch,
       ra.csc_id       AS csc_id_a, rb.csc_id AS csc_id_b,
       (ra.csc_id <> rb.csc_id) AS crosses_depot_boundary
FROM segment_switchgear a
JOIN segment_switchgear b
  ON a.switch_ref = b.switch_ref AND a.register_id < b.register_id
JOIN segment_register ra ON ra.register_id = a.register_id
JOIN segment_register rb ON rb.register_id = b.register_id;


CREATE OR REPLACE SQL SECURITY INVOKER VIEW v_segment_link_quality AS
SELECT 'SWITCH_NOT_FOUND' AS issue_code, 'WARNING' AS severity,
       sr.csc_id, sr.segment_code AS entity,
       CONCAT('Switch ', ss.switch_ref, ' is referenced by segment ',
              sr.segment_code, ' but is not in the switch list.') AS description
FROM segment_switchgear ss
JOIN segment_register sr ON sr.register_id = ss.register_id
WHERE ss.switchgear_id IS NULL
UNION ALL
SELECT 'TRANSFORMER_NOT_FOUND', 'INFO', sr.csc_id, sr.segment_code,
       CONCAT('Transformer reference "', st.transformer_ref, '" on segment ',
              sr.segment_code, ' does not match any SIN in the register.')
FROM segment_transformer st
JOIN segment_register sr ON sr.register_id = st.register_id
WHERE st.transformer_id IS NULL
UNION ALL
SELECT 'SEGMENT_NO_LENGTH', 'ERROR', sr.csc_id, sr.segment_code,
       CONCAT('Segment ', sr.segment_code, ' has no recorded length, so it is ',
              'missing from every line-length total.')
FROM segment_register sr
WHERE sr.length_km IS NULL AND sr.status = 'ACTIVE'
UNION ALL
SELECT 'SEGMENT_NO_FEEDER', 'WARNING', sr.csc_id, sr.segment_code,
       CONCAT('Segment ', sr.segment_code, ' is not assigned to a feeder.')
FROM segment_register sr
WHERE sr.feeder_id IS NULL AND sr.status = 'ACTIVE'
UNION ALL
SELECT 'SWITCH_NOT_ON_SEGMENT', 'INFO', sw.csc_id, sw.switch_code,
       CONCAT('Switch ', sw.switch_code, ' is in the switch list but no ',
              'segment references it.')
FROM switchgear sw
WHERE sw.status = 'ACTIVE'
  AND NOT EXISTS (SELECT 1 FROM segment_switchgear ss
                   WHERE ss.switchgear_id = sw.switchgear_id);


